"""Read-only management contrast audit. No form submission, deletion or production access."""
import json
from pathlib import Path
from playwright.sync_api import sync_playwright
out=Path('test-results/v138/theme-audit');out.mkdir(parents=True,exist_ok=True)
seed=json.loads(Path('test-results/v138/ui-seed.json').read_text());findings=[];screens=[]
sections=['welcome','exam','results','result-editor','data-delete','fmt-share','fmt-upload','txt-converter','share-links','school-add','publishers','answer-keys','students','student-codes','calendar','rebuilder','pdf-tools','dealers','dealer-activities','system-users','store','search-history','test-center','publisher-logos','system-center','blog','files','contact-inbox','audit-logs','exam-schedule','account']
script='''()=>{const rgba=s=>{const a=(s.match(/[\\d.]+/g)||[]).map(Number);return [a[0]||0,a[1]||0,a[2]||0,a.length>3?a[3]:1]},blend=(a,b)=>[0,1,2].map(i=>a[i]*a[3]+b[i]*(1-a[3])),lum=a=>a.map(v=>v/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4).reduce((s,v,i)=>s+v*[.2126,.7152,.0722][i],0),rows=[];for(const e of document.querySelectorAll('.dashboard-main button,.dashboard-main a,.dashboard-main label,.dashboard-main th,.dashboard-main td,.dashboard-main strong,.dashboard-main small,.dashboard-main p,.dashboard-main legend,.dashboard-main input,.dashboard-main select,.dashboard-main textarea,.dashboard-main summary,.dashboard-main h1,.dashboard-main h2,.dashboard-main h3')){const text=e.matches('input,textarea')?e.value:e.matches('select')?e.selectedOptions[0]?.textContent:[...e.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent).join('').trim();if(!text||!e.getClientRects().length||e.closest(':disabled,[aria-disabled=true]'))continue;const style=getComputedStyle(e);if(style.visibility==='hidden'||style.display==='none')continue;let ancestors=[],p=e;while(p){ancestors.unshift(p);p=p.parentElement;}let bg=[255,255,255],opacity=1;for(const p of ancestors){const s=getComputedStyle(p);bg=blend(rgba(s.backgroundColor),bg);opacity*=Number(s.opacity);}if(opacity<.95)continue;const color=blend(rgba(style.color),bg),a=lum(color),b=lum(bg),ratio=(Math.max(a,b)+.05)/(Math.min(a,b)+.05),large=parseFloat(style.fontSize)>=24||(parseFloat(style.fontSize)>=18.66&&Number(style.fontWeight)>=700);if(ratio<(large?3:4.5)-.01)rows.push({text:text.slice(0,120),tag:e.tagName,className:e.className,ratio,fontSize:style.fontSize,color:style.color,background:bg});}return rows;}'''
with sync_playwright() as p:
 b=p.chromium.launch(headless=True,args=['--no-sandbox']);c=b.new_context(viewport={'width':1440,'height':1000});c.add_init_script('sessionStorage.setItem("kurumsal-auth-token",'+json.dumps(seed['token'])+');localStorage.setItem("ks-analytics-consent","denied");sessionStorage.setItem("kurumsal-splash-seen","1");');page=c.new_page();page.set_default_timeout(15000)
 for theme in ['light','dark']:
  c.add_init_script('localStorage.setItem("kurumsal-theme",'+json.dumps(theme)+')')
  for section in sections:
   page.goto('http://localhost:3115/panel?section='+section,wait_until='domcontentloaded');page.locator('main.dashboard').wait_for();page.wait_for_timeout(350);assert page.locator('html').get_attribute('data-theme')==theme;rows=page.evaluate(script);screens.append({'section':section,'theme':theme,'findings':len(rows)});findings.extend({'section':section,'theme':theme,**r} for r in rows)
   if rows:page.screenshot(path=str(out/(section+'-'+theme+'.png')),full_page=True)
 (out/'findings.json').write_text(json.dumps({'screens':screens,'findings':findings},ensure_ascii=False,indent=2));b.close()
 print(json.dumps({'screens':len(screens),'findings':len(findings),'critical':sum(r['ratio']<3 for r in findings)}));assert not findings, 'Contrast findings remain; inspect theme-audit/findings.json'
